package dev.gravaai.media.ffmpeg;

import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;

/**
 * Locates the committed media fixtures in {@code java/parity/fixtures/media} (plan §5.7,
 * §6.1). The fixtures are generated by {@code java/native/make-fixtures.sh}.
 */
final class MediaFixtures {

	private static final List<Path> CANDIDATES = List.of(
			Path.of("parity", "fixtures", "media"),
			Path.of("..", "parity", "fixtures", "media"),
			Path.of("..", "..", "parity", "fixtures", "media"));

	private MediaFixtures() {}

	static Path directory() {
		String explicit = System.getProperty("gravaai.media.fixtures.dir");
		if (explicit != null && !explicit.isBlank()) {
			return Path.of(explicit);
		}
		for (Path candidate : CANDIDATES) {
			if (Files.isDirectory(candidate)) {
				return candidate.toAbsolutePath().normalize();
			}
		}
		throw new IllegalStateException("media fixtures not found; run java/native/make-fixtures.sh"
				+ " (tried " + CANDIDATES + ")");
	}

	/** The h264 fixture: 2 s, 1080p60, no audio. */
	static Path h264() {
		return fixture("h264-1080p60.mp4");
	}

	/** The vp9 fixture: 2 s, 720p30 WebM, no audio. */
	static Path vp9() {
		return fixture("vp9-720p30.webm");
	}

	/** The audio fixture: 2 s, 48 kHz stereo AAC. */
	static Path aac() {
		return fixture("aac-48k-stereo.m4a");
	}

	/** The rotated clip: 1080x1920 sensor, display matrix rotation 90. */
	static Path rotated() {
		return fixture("rotated-phone.mp4");
	}

	private static Path fixture(String name) {
		Path file = directory().resolve(name);
		if (!Files.isRegularFile(file)) {
			throw new IllegalStateException("fixture missing: " + file
					+ " (run java/native/make-fixtures.sh)");
		}
		return file;
	}
}
